<script setup lang="ts">
import {displayText,displayJson,initials} from "./stores/presentation"
import {computed,onMounted,ref} from 'vue'
import {LayoutDashboard,FolderOpen,Plus,BookOpen,ShieldCheck,ArrowUpRight,LogOut,Building2} from 'lucide-vue-next'
import {api,token} from './api'
import {desk,inr} from './stores/desk'
import type {Case} from './types'
import Landing from './pages/Landing.vue'
import Borrower from './pages/Borrower.vue'
import NewApplication from './pages/NewApplication.vue'
import Workspace from './pages/Workspace.vue'
import StatusBadge from './components/StatusBadge.vue'
const portal=ref('landing'),role=ref(sessionStorage.getItem('msme_role')||''),panSearch=ref('')
function choosePortal(p:string){portal.value=p;sessionStorage.setItem('msme_portal',p)}
const loggedIn=ref(!!token()),credential=ref(''),cases=ref<Case[]>([]),counts=ref<Record<string,number>>({}),total=ref(0),ledger=ref<any[]>([]),selected=ref('')
const selectedStatus=ref('')
const visibleCases=computed(()=>cases.value.filter(c=>(!selectedStatus.value||c.status===selectedStatus.value)&&displayText([c.data.business,c.data.applicant,c.data.journey?.pan,c.id].join(' ')).toLowerCase().includes(panSearch.value.toLowerCase())))
async function refresh(){desk.busy=true;desk.error='';try{const data=await api('/applications?limit=100');cases.value=data.items;counts.value=data.counts;total.value=data.total;if(desk.view==='ledger')ledger.value=(await api('/ledger?limit=100')).items}catch(e){desk.error=(e as Error).message}finally{desk.busy=false}}
async function login(){sessionStorage.setItem('msme_token',credential.value);try{const me=await api('/me');role.value=me.role;sessionStorage.setItem('msme_role',me.role);loggedIn.value=true;await refresh()}catch(e){sessionStorage.removeItem('msme_token');desk.error=(e as Error).message}}
function logout(){sessionStorage.removeItem('msme_token');loggedIn.value=false;desk.error='';credential.value=''}
async function navigate(view:string){desk.view=view;selected.value='';await refresh()}
function open(id:string){selected.value=id;desk.view='workspace';desk.error=''}
onMounted(()=>{if(loggedIn.value)refresh()})
</script>
<template><Landing v-if="portal==='landing'" @borrower="choosePortal('borrower')" @staff="choosePortal('staff')"/><Borrower v-else-if="portal==='borrower'" @staff="choosePortal('staff')" @home="choosePortal('landing')"/><div v-else-if="!loggedIn" class="login-screen"><form class="panel login" @submit.prevent="login"><div class="brand"><div class="brand-mark"><span class="sidebar-glyph">m·</span></div>MSME<span>CAPITAL</span></div><div class="eyebrow">CREDIT WORKSPACE</div><h1>A better perspective.<br>A considered decision.</h1><p>A connected workspace for considered credit decisions.</p><label>Staff access token<input v-model="credential" type="password" required autocomplete="current-password" placeholder="Enter credit officer or manager token"></label><p class="error" v-if="desk.error">{{displayText(desk.error)}}</p><button class="primary">Enter underwriting desk →</button><small>Use the access credentials provided by your administrator.</small><button type="button" @click="choosePortal('borrower')">← Borrower portal</button></form></div><div v-else class="shell"><aside><div class="brand"><div class="brand-mark"><span class="sidebar-glyph">m·</span></div>MSME<span>CAPITAL</span></div><div class="nav-caption">WORKSPACE</div><nav><button :class="{active:desk.view==='dashboard'}" @click="navigate('dashboard')"><LayoutDashboard :size="18"/> Overview</button><button :class="{active:['applications','workspace'].includes(desk.view)}" @click="navigate('applications')"><FolderOpen :size="18"/> Applications <span class="nav-count">{{displayText(total)}}</span></button><button :class="{active:desk.view==='new'}" @click="navigate('new')"><Plus :size="18"/> New application</button><button :class="{active:desk.view==='ledger'}" @click="navigate('ledger')"><BookOpen :size="18"/> Sanction register</button></nav><div class="sidebar-bottom"><div class="safe-mode"><ShieldCheck :size="18"/><div><strong>Every decision, considered.</strong><small>Evidence-led. Human-approved.</small></div></div><button class="logout" @click="logout"><LogOut :size="16"/> Sign out</button><small>MSME CAPITAL / CREDIT WORKSPACE</small></div></aside><div class="main-wrap"><header><div><span class="subtle">Workspace</span><span class="breadcrumb">/</span>{{displayText(desk.view==='workspace'?'Case review':desk.view==='new'?'New application':'Underwriting desk')}}</div><div class="header-right"><span class="environment-dot"></span> {{displayText(role==='manager'?'BRANCH MANAGER':'CREDIT OFFICER')}} <button @click="logout">Sign out</button> <button @click="choosePortal('borrower')">Borrower portal</button></div></header><main><div role="alert" v-if="desk.error" class="error-banner">{{displayText(desk.error)}}<button @click="desk.error=''">Dismiss</button></div><template v-if="desk.view==='dashboard'||desk.view==='applications'"><div class="page-heading"><div><div class="eyebrow">YOUR CREDIT WORKSPACE</div><h1>{{displayText(desk.view==='dashboard'?'A clearer view of business.':'Applications')}}</h1><p>From source evidence to a considered credit decision.</p></div><button class="primary" @click="navigate('new')"><Plus :size="16"/> New application</button></div><div class="metric-grid four" v-if="desk.view==='dashboard'"><div class="panel"><small>TOTAL APPLICATIONS</small><strong class="metric">{{displayText(total)}}</strong><span class="metric-caption">Across your workspace</span></div><div class="panel"><small>AWAITING REVIEW</small><strong class="metric green">{{displayText(counts.awaiting_review||0)}}</strong><span class="metric-caption">Analysis complete</span></div><div class="panel"><small>MORE EVIDENCE</small><strong class="metric">{{displayText(counts.needs_evidence||0)}}</strong><span class="metric-caption">Clarification required</span></div><div class="panel"><small>NEEDS ATTENTION</small><strong class="metric">{{displayText((counts.failed||0)+(counts.processing_failed||0))}}</strong><span class="metric-caption">Action required</span></div></div><div v-if="desk.view==='dashboard'" class="workflow-banner"><div class="workflow-emblem"><ShieldCheck :size="28"/></div><div><h2>Good decisions start with a complete picture.</h2><p>Bring the records, the conversation and the numbers together.</p></div><span class="banner-tag">HUMAN REVIEW REQUIRED</span></div><section class="panel"><div class="section-title"><h2>{{displayText(desk.view==='dashboard'?'Recent applications':'Application register')}}</h2><button class="text-button" @click="refresh">Refresh ↻</button></div><div class="queue-filters"><button v-for="(title,status) in {'':'All applications',awaiting_review:'Ready for review',needs_evidence:'Needs evidence',approved:'Approved'}" :class="{selected:selectedStatus===status}" @click="selectedStatus=String(status)">{{title}} <span>{{status?counts[status]||0:total}}</span></button></div><form class="pan-search" @submit.prevent="refresh"><input v-model="panSearch" aria-label="Find an application" placeholder="Search by business, applicant or reference"><button>Find application</button><button type="button" @click="panSearch='';selectedStatus='';refresh()">Clear</button></form><div class="table-wrap"><table><thead><tr><th>Business / applicant</th><th>Requested amount</th><th>Tenure</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><tr v-for="c in visibleCases" :key="c.id"><td><div class="company-cell"><span class="company-avatar small-avatar">{{initials(c.data.business)}}</span><div><button class="case-link" @click="open(c.id)">{{displayText(c.data.business)}}</button><small>{{displayText(c.data.applicant)}} · {{displayText(c.id.slice(0,8))}}</small></div></div></td><td>{{displayText(inr(c.data.requested_amount))}}</td><td>{{displayText(c.data.tenure_months)}} months</td><td><StatusBadge :value="c.status"/></td><td>{{displayText(new Date(c.created_at).toLocaleDateString('en-IN'))}}</td><td><button class="icon-button" aria-label="Open application" @click="open(c.id)"><ArrowUpRight :size="18"/></button></td></tr><tr v-if="!visibleCases.length"><td colspan="6" class="empty"><FolderOpen :size="30"/><h3>{{displayText(desk.busy?'Loading applications…':'Your first case starts here.')}}</h3><p>Create an application and bring its business records together.</p><button @click="navigate('new')">Create application →</button></td></tr></tbody></table></div><div class="table-footer">Showing {{displayText(visibleCases.length)}} of {{displayText(total)}} applications · newest first <span>All amounts in INR</span></div></section></template><NewApplication v-if="desk.view==='new'" @created="open"/><Workspace v-if="desk.view==='workspace'" :key="selected" :id="selected"/><template v-if="desk.view==='ledger'"><div class="page-heading"><div><div class="eyebrow">APPROVED APPLICATIONS</div><h1>Sanction register</h1><p>An organized record of sanctioned terms and approval decisions.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Case</th><th>Principal</th><th>EMI</th><th>Reviewer</th><th>Recorded</th></tr></thead><tbody><tr v-for="entry in ledger"><td><button class="case-link" @click="open(entry.case_id)">{{displayText(entry.case_id.slice(0,8))}}</button></td><td>{{displayText(inr(entry.data.terms.proposed_principal))}}</td><td>{{displayText(inr(entry.data.terms.monthly_installment))}}</td><td>{{displayText(entry.data.reviewer_id)}}</td><td>{{displayText(new Date(entry.created_at).toLocaleString())}}</td></tr><tr v-if="!ledger.length"><td colspan="5" class="empty">Approved applications will appear here.</td></tr></tbody></table></div></div></template><footer>MSME Capital <span>Evidence → Analysis → Human review</span></footer></main></div></div></template>
